(()=>{
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
const portraits={anand:{name:'Anand Nahar',role:'Co-founder · Chairman & Director',area:'Strategy & brand building',bio:'Anand co-founded Zorko in Surat in 2020. With an engineering background and experience in financial markets, his work spans business strategy, brand building, and expansion.'},amrit:{name:'Amrit Nahar',role:'Co-founder · Whole-time Director',area:'Operations & company direction',bio:'Amrit co-founded Zorko with his brother Anand. His background in environmental engineering and anthropology informs his focus on operations, processes, and the company’s vegetarian food vision.'},neel:{name:'Neel Savani',role:'Chief Operating Officer',area:'Operational leadership',bio:'Neel Savani is Zorko’s Chief Operating Officer. The role connects operational planning with the everyday execution behind the company’s growing network.'},nirmal:{name:'Nirmal Somani',role:'Chief Financial Officer',area:'Financial leadership',bio:'Nirmal Somani serves as Chief Financial Officer, leading the finance function within Zorko’s corporate management team.'},tina:{name:'Tina Jariwala',role:'Company Secretary',area:'Corporate governance',bio:'Tina Jariwala serves as Company Secretary, supporting the company’s corporate governance and secretarial function.'}};
const dialog=document.querySelector('#person-dialog');document.querySelectorAll('[data-person]').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.person,p=portraits[id];if(!dialog||!p)return;dialog.querySelector('#person-name').textContent=p.name;dialog.querySelector('#person-role').textContent=p.role;dialog.querySelector('#person-bio').textContent=p.bio;dialog.querySelector('#person-area').textContent=p.area;dialog.querySelector('#person-image').src=`assets/official/${id}.webp`;dialog.querySelector('#person-image').alt=p.name;dialog.showModal()}));dialog?.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog?.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
const tabs=[...document.querySelectorAll('.benefit-tabs [role="tab"]')];function activate(tab){tabs.forEach(t=>{const selected=t===tab;t.setAttribute('aria-selected',String(selected));t.tabIndex=selected?0:-1;document.getElementById(t.getAttribute('aria-controls')).hidden=!selected})}tabs.forEach((t,i)=>{t.tabIndex=i? -1:0;t.addEventListener('click',()=>activate(t));t.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=tabs[(i+1)%tabs.length];if(e.key==='ArrowLeft')next=tabs[(i+tabs.length-1)%tabs.length];if(e.key==='Home')next=tabs[0];if(e.key==='End')next=tabs.at(-1);if(next){e.preventDefault();activate(next);next.focus()}})});
const photos=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('photo-visible');photos.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.photo-reveal').forEach(e=>photos.observe(e));
const nav=document.querySelector('.career-subnav');if(nav){const links=[...nav.querySelectorAll('a')],sections=links.map(a=>document.getElementById(a.hash.slice(1))).filter(Boolean);let current='',pending=false;function select(id){if(id===current)return;current=id;links.forEach(a=>{if(a.hash==='#'+id){a.setAttribute('aria-current','location');const left=a.offsetLeft-(nav.clientWidth-a.offsetWidth)/2;nav.scrollTo({left:Math.max(0,left),behavior:reduce?'instant':'smooth'})}else a.removeAttribute('aria-current')})}function sync(){let selected=sections[0];for(const section of sections){if(section.getBoundingClientRect().top<=innerHeight*.36)selected=section}if(selected)select(selected.id);pending=false}links.forEach(a=>a.addEventListener('click',()=>select(a.hash.slice(1))));addEventListener('scroll',()=>{if(!pending){pending=true;requestAnimationFrame(sync)}},{passive:true});addEventListener('resize',sync);sync()}
document.querySelectorAll('.leader-rail').forEach(rail=>{
 const section=rail.closest('.leadership-section'),prev=section.querySelector('[data-leader-prev]'),next=section.querySelector('[data-leader-next]');
 const step=()=>rail.querySelector('.leader-card').getBoundingClientRect().width+parseFloat(getComputedStyle(rail).gap||28);
 const sync=()=>{prev.disabled=rail.scrollLeft<3;next.disabled=rail.scrollLeft+rail.clientWidth>=rail.scrollWidth-3};
 prev.addEventListener('click',()=>rail.scrollBy({left:-step(),behavior:reduce?'instant':'smooth'}));next.addEventListener('click',()=>rail.scrollBy({left:step(),behavior:reduce?'instant':'smooth'}));rail.addEventListener('scroll',sync,{passive:true});addEventListener('resize',sync);sync();
 let start=0,scrollStart=0,pressed=false,dragged=false;
 rail.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0)return;pressed=true;dragged=false;start=e.clientX;scrollStart=rail.scrollLeft});
 rail.addEventListener('pointermove',e=>{if(!pressed)return;const dx=e.clientX-start;if(Math.abs(dx)>6){dragged=true;rail.classList.add('is-dragging');if(!rail.hasPointerCapture(e.pointerId))rail.setPointerCapture(e.pointerId);rail.scrollLeft=scrollStart-dx;e.preventDefault()}});
 const finish=()=>{pressed=false;rail.classList.remove('is-dragging')};rail.addEventListener('pointerup',finish);rail.addEventListener('pointercancel',finish);rail.addEventListener('lostpointercapture',finish);rail.addEventListener('pointerleave',()=>{if(!dragged)finish()});rail.addEventListener('click',e=>{if(dragged){e.preventDefault();e.stopPropagation();dragged=false}},true);
});
document.querySelectorAll('.leader-grid,.experience-grid,.news-grid,.principle-grid,.culture-cards').forEach(grid=>[...grid.children].forEach((child,i)=>child.style.setProperty('--reveal-delay',`${Math.min(i%4,3)*85}ms`)));
const headingObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('heading-revealed');headingObserver.unobserve(e.target)}}),{threshold:.12});
document.querySelectorAll('main h1,main h2').forEach(h=>{if(!h.textContent.trim()||h.closest('dialog'))return;const lines=h.innerHTML.split(/<br\s*\/?>/i);h.innerHTML=lines.map((line,i)=>`<span class="heading-line"><span class="heading-ink" style="--line-delay:${i*100}ms">${line}</span></span>`).join('');h.classList.add('animated-heading');headingObserver.observe(h)});
document.querySelectorAll('.photo-reveal').forEach(parent=>{const img=parent.querySelector(':scope > img');if(!img)return;const frame=document.createElement('div');frame.className='photo-frame';img.before(frame);frame.append(img)});
if(!reduce){const images=[...document.querySelectorAll('.home-photographs .photo-frame,.about-photo-pair .photo-frame')];let queued=false;const drift=()=>{if(innerWidth>800)images.forEach((frame,i)=>{const r=frame.getBoundingClientRect();if(r.bottom<0||r.top>innerHeight)return;const progress=(innerHeight/2-r.top-r.height/2)/innerHeight;frame.style.setProperty('--image-drift',`${Math.max(-14,Math.min(14,progress*(i%2?24:-18)))}px`)});queued=false};addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(drift)}},{passive:true});drift()}
})();
